Matching Ayahs
- = Alif, Lám, Mím. 2:1; 3:1; 29:1; 30:1; 31:1; 32:1
- = Tí sú na správnom vedení od svojho Pána a tí sú úspešní. 2:5; 31:5
- = O deti Izraela, spomeňte si na Moju priazeň, ktorú som vám preukázal, a že som vás povýšil nad všetky národy (svety). 2:47; 2:122
- = To bol národ, ktorý už pominul. Jemu patrí, čo si zaslúžil, a vám patrí, čo ste si zaslúžili. A nebudete vypočúvaní za to, čo oni robili. 2:134; 2:141
- = Večne v ňom ostanú; trest im nebude zmiernený a nebude im daný odklad. 2:162; 3:88
- = Okrem tých, ktorí sa po tomto kajajú a napravia. Lebo Boh je odpúšťajúci, milosrdný. 3:89; 24:5
- = A tí, ktorí neveria a popierajú Naše znamenia – tí sú obyvateľmi pekla. 5:10; 5:86
- = A nepríde im žiadne znamenie zo znamení ich Pána, aby sa od neho neodvrátili. 6:4; 36:46
- = A už pred tebou boli poslovia zosmiešňovaní, ale tých, ktorí sa im vysmievali, postihlo to, z čoho si robili posmech. 6:10; 21:41
- = Povedz: "Bojím sa, ak neposlúchnem svojho Pána, trestu veľkého dňa." 6:15; 39:13
- = A postihlo ich zemetrasenie a zostali v svojich domoch ležať tvárami k zemi. 7:78; 7:91
- = I hodil svoju palicu, a hľa, bola zjavným hadom. 7:107; 26:32
- = A vytiahol svoju ruku, a hľa, bola biela (žiariaca) pre tých, čo sa pozerali. 7:108; 26:33
- = Povedali: "Uverili sme v Pána svetov." 7:121; 26:47
- = Pána Mojžiša a Árona. 7:122; 26:48
- = A Ja im dám odklad. Moja nástraha je pevná. 7:183; 68:45
- = On je ten, ktorý poslal svojho Posla so správnym vedením a náboženstvom pravdy, aby ho povýšil nad všetky náboženstvá, aj keď to mnohobožcom nepríjemné. 9:33; 61:9
- = Prorok, bojuj proti neveriacim a pokrytcom a buď prísny na nich! Ich útočiskom bude peklo a aký hrozný je to cieľ! 9:73; 66:9
- = A hovoria: "Kedy sa splní tento sľub, ak ste pravdovravní?" 10:48; 21:38; 27:71; 34:29; 36:48; 67:25
- = A poslali sme Mojžiša s Našimi znameniami a so zjavnou mocou. 11:96; 40:23
- = A dali sme Mojžišovi Písmo, ale vznikli o ňom nezhody. A nebyť slova, ktoré predišlo od tvojho Pána, bolo by medzi nimi rozhodnuté. A oni sú o ňom na pochybách. 11:110; 41:45
- = To nie je pre Boha ťažké. 14:20; 35:17
- = "A keď ho dokončím a vdýchnem do neho z môjho ducha, padnite pred ním na zem." 15:29; 38:72
- = A anjeli sa všetci spolu poklonili. 15:30; 38:73
- = (Boh) povedal: "Vyjdi z neho, lebo si prekliaty." 15:34; 38:77
- = (Iblis) povedal: "Pane môj, daj mi odklad do dňa, keď budú vzkriesení." 15:36; 38:79
- = (Boh) povedal: "Budeš z tých, ktorým sa odklad dáva." 15:37; 38:80
- = Do dňa určitého času." 15:38; 38:81
- = Okrem tvojich úprimných služobníkov medzi nimi. 15:40; 38:83
- = Bohabojní budú v záhradách a pri prameňoch. 15:45; 51:15
- = Povedal: "Aká je vaša úloha, poslovia?" 15:57; 51:31
- = Povedali: "Sme vyslaní k zločinnému ľudu." 15:58; 51:32
- = Tí, ktorí uverili a nezmiešali svoju vieru s krivdou – tí majú istotu a tí sú správne vedení. 16:42; 29:59
- = Aby boli nevďační za to, čo sme im dali. Užívajte si, ale čoskoro sa dozviete. 16:55; 30:34
- = Potom išiel po ceste. 18:89; 18:92
- = Choď k faraónovi, lebo on sa vzbúril. 20:24; 79:17
- = A tí, čo chránia svoje pohlavné orgány. 23:5; 70:29
- = Okrem svojich manželiek a tých, ktorých ovládla ich pravá ruka, pretože tí nie sú obviňovaní. 23:6; 70:30
- = A ktokoľvek túži po niečom viac, tí prestupujú hranice. 23:7; 70:31
- = A tí, čo dodržiavajú zverené veci a svoje záväzky. 23:8; 70:32
- = Povedal: "Pane môj, pomôž mi, pretože ma obvinili z klamstva." 23:26; 23:39
- = Tá, Sín, Mím. 26:1; 28:1
- = Toto sú verše jasného Písma. 26:2; 28:2
- = V tomto je naozaj znamenie, ale väčšina z nich neverí. 26:8; 26:67; 26:103; 26:121; 26:174; 26:190
- = A tvoj Pán – On je Mocný, Milosrdný. 26:9; 26:68; 26:104; 26:122; 26:140; 26:159; 26:175; 26:191
- = A potopili sme tých druhých. 26:66; 37:82
- = Ja som pre vás dôveryhodný posol. 26:107; 26:125; 26:143; 26:162; 26:178
- = Bojte sa Boha a poslúchajte ma! 26:108; 26:110; 26:126; 26:131; 26:144; 26:150; 26:163; 26:179
- = A nežiadam od vás za to odmenu; moja odmena je len od Pána svetov. 26:109; 26:127; 26:145; 26:164; 26:180
- = V záhradách a pri prameňoch. 26:147; 44:52
- = Povedali: "Ty si len jeden z očarených." 26:153; 26:185
- = Okrem jeho ženy – určili sme, že bude medzi tými, ktorí zostali. 26:171; 37:135
- = Potom sme tých druhých zničili. 26:172; 37:136
- = A zoslali sme na nich dážď (kameňov) a aký zlý to bol dážď pre varovaných! 26:173; 27:58
- = Chcú oni urýchliť trest? 26:204; 37:176
- = Tí, ktorí vykonávajú modlitbu, dávajú almužnu a pevne veria v život posmrtný. 27:3; 31:4
- = A (spomeň si) na Deň, keď ich zavolá a povie: "Kde sú moji spoločníci, ktorých ste vymýšľali?" 28:62; 28:74
- = A naši predkovia? 37:17; 56:48
- = A budú sa k sebe obracať a navzájom sa vypytovať. 37:27; 52:25
- = Okrem úprimných Božích služobníkov. 37:40; 37:74; 37:128; 37:160
- = V záhradách slasti. 37:43; 56:12
- = A zanechali sme o ňom (pamiatku) pre nasledujúcich: 37:78; 37:108; 37:129
- = A tak odmeňujeme tých, ktorí dobro konajú. 37:80; 37:121; 37:131; 77:44
- = On bol naším veriacim služobníkom. 37:81; 37:111; 37:132
- = Čo je s vami? Ako môžete súdiť? 37:154; 68:36
- = Toto je len pripomenutie svetom. 38:87; 81:27
- = Zoslanie Písma od Boha, Mocného, Múdreho. 39:1; 45:2; 46:2
- = Há, Mím. 40:1; 41:1; 42:1; 43:1; 44:1; 45:1; 46:1
- = Pri jasnom Písme! 43:2; 44:2
- = Nech ich teda, nech sa zabávajú a hrajú, až kým nestretnú svoj deň, ktorý im bol sľúbený. 43:83; 70:42
- = (Bude im povedané): "Jedzte a pite s pôžitkom za to, čo ste konali." 52:19; 77:43
- = Alebo žiadaš od nich odmenu, takže by boli zaťažení dlhmi? 52:40; 68:46
- = Alebo majú vedomosť o skrytom, a preto ho zapisujú? 52:41; 68:47
- = A aký bol môj trest a moje varovania! 54:16; 54:21; 54:30
- = A uľahčili sme Korán na zapamätanie. Je niekto, kto si ho pripomenie? 54:17; 54:22; 54:32; 54:40
- = Ktoré z dobrodiní svojho Pána popierate? 55:13; 55:16; 55:18; 55:21; 55:23; 55:25; 55:28; 55:30; 55:32; 55:34; 55:36; 55:38; 55:40; 55:42; 55:45; 55:47; 55:49; 55:51; 55:53; 55:55; 55:57; 55:59; 55:61; 55:63; 55:65; 55:67; 55:69; 55:71; 55:73; 55:75; 55:77
- = Skupina prvých. 56:13; 56:39
- = A my sme boli pripravení? 56:67; 68:27
- = Oslavuj teda meno svojho Pána Veľkého! 56:74; 56:96; 69:52
- = Je to zoslanie od Pána svetov. 56:80; 69:43
- = Všetko, čo je na nebesiach a na zemi, oslavuje Boha, a On je Mocný, Múdry. 59:1; 61:1
- = Keď sa mu prednášajú Naše verše, hovorí: "Povesti starých!" 68:15; 83:13
- = A on bude v príjemnom živote. 69:21; 101:7
- = Vo vyvýšenej záhrade. 69:22; 88:10
- = A nepodnecuje k nakŕmeniu chudobného. 69:34; 107:3
- = Toto je naozaj reč vznešeného Posla. 69:40; 81:19
- = Toto je pripomenutie. A kto chce, nech si zvolí cestu k svojmu Pánovi. 73:19; 76:29
- = A kto chce, nech si to pripomenie. 74:55; 80:12
- = Beda v ten deň tým, čo popierajú! 77:15; 77:19; 77:24; 77:28; 77:34; 77:37; 77:40; 77:45; 77:47; 77:49; 83:10
- = Spravodliví budú naozaj v slasti. 82:13; 83:22
- = Je to písaná kniha. 83:9; 83:20
- = Na pohovkách budú hľadieť. 83:23; 83:35
- = A poslúchlo svojho Pána a je povinné. 84:2; 84:5
- = A ja neuctievam to, čo vy uctievate. 109:3; 109:5
