- Ľudia môj, konajte podľa svojho postavenia, ja tiež konám; potom zistíte, kto. (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ مَن) 6:135; 11:93
