- Všetko, čo je na zemi, a ešte raz toľko, aby sa tým vykúpili z. (مَّا فِي الْأَرْضِ جَمِيعًا وَمِثْلَهُ مَعَهُ لِيَفْتَدُوا بِهِ مِنْ) 5:36; 39:47
