- Rajské záhrady, pod ktorými tečú rieky, v nich budú večne. (جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا) 4:57; 4:122; 5:119; 64:9; 65:11
- Ty uvádzaš noc do dňa a uvádzaš deň do noci. (تُولِجُ اللَّيْلَ فِي النَّهَارِ وَتُولِجُ النَّهَارَ فِي اللَّيْلِ) 3:27; 22:61; 31:29; 35:13; 57:6
- Oslavuje Allaha všetko, čo je na nebesiach a na zemi. (سَبَّحَ لِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 59:1; 61:1; 62:1; 64:1
- Uctievajte Allaha, nemáte iného boha okrem Neho. Či sa nebudete báť? (اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا) 7:65; 11:84; 23:23; 23:32
- Keď sme anjelom povedali: Padnite na tvár pred Adamom!, padli na tvár všetci okrem Iblisa. (وَإِذْ قُلْنَا لِلْمَلَائِكَةِ اسْجُدُوا لِآدَمَ فَسَجَدُوا إِلَّا إِبْلِيسَ) 2:34; 17:61; 18:50; 20:116
- Allah vie, čo je na nebesiach a na zemi. (اللَّهُ وَيَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 3:29; 5:97; 49:16; 58:7
- Rajské záhrady, pod ktorými tečú rieky, v nich budú večne, a to. (جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ) 4:13; 5:85; 9:89; 57:12
- Jeho odmena je u jeho Pána, a niet pre nich strachu, ani oni. (أَجْرُهُ عِندَ رَبِّهِ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ) 2:112; 2:262; 2:274; 2:277
- U jeho Pána, a niet pre nich strachu, ani nebudú zarmútení. (عِندَ رَبِّهِ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ) 2:112; 2:262; 2:274; 2:277
- Kto nasleduje správnu cestu, nasleduje ju pre svoj prospech, a kto zablúdi. (فَمَنِ اهْتَدَى فَإِنَّمَا يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ) 10:108; 17:15; 27:92
- Nasleduje ju pre svoj prospech, a kto zablúdi, zablúdi na svoju škodu. (يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا) 10:108; 17:15; 39:41
- Prečo mu nebolo zoslané znamenie od jeho Pána? Povedz: Veru. (لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ فَقُلْ إِنَّمَا) 10:20; 13:27; 29:50
- Tí, ktorí uverili a konali dobré skutky, pre nich je odmena nepretržitá. (الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ) 41:8; 84:25; 95:6
- Ty vyvádzaš živé z mŕtveho a vyvádzaš mŕtve z živého. (وَتُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَتُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّ) 3:27; 10:31; 30:19
- Ten, kto nesúdi podľa toho, čo zoslal Allah, tí sú. (وَمَن لَّمْ يَحْكُم بِمَا أَنزَلَ اللَّهُ فَأُولَئِكَ هُمُ) 5:44; 5:45; 5:47
- On stvoril nebesia a zem a to, čo je medzi nimi, v šiestich dňoch. (خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا فِي سِتَّةِ أَيَّامٍ) 25:59; 32:4; 50:38
- Veru, Allah je láskavý k ľuďom, ale väčšina. (إِنَّ اللَّهَ لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَ) 2:243; 10:60; 40:61
- Allah im nekrivdil, ale oni sami sebe krivdili. (فَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ وَلَكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ) 9:70; 29:40; 30:9
- On vám odpustí hriechy a uvedie vás do rajských záhrad, pod ktorými tečú rieky. (عَنكُمْ سَيِّئَاتِكُمْ وَلَأُدْخِلَنَّكُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 5:12; 64:9; 66:8
- Zakázal vám mŕtvolu, krv, mäso svine a to, čo bolo zabité pre niekoho iného ako Allaha. (حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ وَالدَّمَ وَلَحْمَ الْخِنزِيرِ وَمَا أُهِلَّ) 2:173; 5:3; 16:115
- Ja sa bojím, ak nebudem poslušný svojmu Pánovi, trestu veľkého dňa. (إِنِّي أَخَافُ إِنْ عَصَيْتُ رَبِّي عَذَابَ يَوْمٍ عَظِيمٍ) 6:15; 10:15; 39:13
- Ale po tom, čo k nim prišlo vedenie, zo závisti medzi sebou. (إِلَّا مِن بَعْدِ مَا جَاءَهُمُ الْعِلْمُ بَغْيًا بَيْنَهُمْ) 3:19; 42:14; 45:17
- Oni vykonávajú modlitbu a dávajú z toho, čo sme im uštedrili, tajne i verejne. (وَأَقَامُوا الصَّلَاةَ وَأَنفَقُوا مِمَّا رَزَقْنَاهُمْ سِرًّا وَعَلَانِيَةً) 13:22; 14:31; 35:29
- Či budeme vzývať namiesto Allaha to, čo nám ani neprospieva, ani neškodí? (مِن دُونِ اللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا) 6:71; 10:106; 25:55
- Veria v to, čo bolo zoslané tebe, a v to, čo bolo zoslané pred tebou. (يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ) 2:4; 4:60; 4:162
- Nevidíš, že Allah zosiela vodu z neba? (أَلَمْ تَرَ أَنَّ اللَّهَ أَنزَلَ مِنَ السَّمَاءِ مَاءً) 22:63; 35:27; 39:21
- Keď o niečom rozhodne, povie mu iba: "Buď!" a ono sa stane. (قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن فَيَكُونُ) 3:47; 19:35; 40:68
- A do Madjanu (poslali sme) ich brata Šu'ajba. Povedal: Ó, môj ľude! Uctievajte Allaha. (وَإِلَى مَدْيَنَ أَخَاهُمْ شُعَيْبًا قَالَ يَاقَوْمِ اعْبُدُوا اللَّهَ) 7:85; 11:84; 29:36
- To sú správy z nepoznateľného, ktoré ti zjavujeme; ty si to nevedel. (ذَلِكَ مِنْ أَنْبَاءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ) 3:44; 11:49; 12:102
- Keď príde ich termín, nemôžu ho ani o hodinu oneskoriť, ani urýchliť. (فَإِذَا جَاءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ) 7:34; 10:49; 16:61
- Nenasledujte kroky satana, veru, on je vaším zjavným nepriateľom. (وَلَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُّبِينٌ) 2:168; 2:208; 6:142
- Medzi ľuďmi sú takí, ktorí sa hádajú o Allahovi bez vedomosti. (وَمِنَ النَّاسِ مَن يُجَادِلُ فِي اللَّهِ بِغَيْرِ عِلْمٍ) 22:3; 22:8; 31:20
- Allah dáva, komu chce, a Allah je nesmierne štedrý. (اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 57:21; 57:29; 62:4
- Každá duša dostane plnú odmenu za to, čo si zaslúžila, a nebude im ukrivdené. (تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:25; 3:161
- Nezabíjajte dušu, ktorú Allah zakázal, okrem s právom. (وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ) 6:151; 17:33; 25:68
- Keď o niečom rozhodne, povie mu iba: "Buď!" (إِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن) 3:47; 19:35; 40:68
- Vojdite do brán pekla, v ktorom budete večne; a aké zlé je obydlie pyšných! (فَادْخُلُوا أَبْوَابَ جَهَنَّمَ خَالِدِينَ فِيهَا فَلَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ) 16:29; 39:72; 40:76
- Či si nevidel tých, ktorým bola daná časť Knihy? (أَلَمْ تَرَ إِلَى الَّذِينَ أُوتُوا نَصِيبًا مِّنَ الْكِتَابِ) 3:23; 4:44; 4:51
- Pre nich sú rajské záhrady, pod ktorými tečú rieky, a budú v nich večne. (لَهُمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:198; 5:119; 9:89
- Ó, môj ľude! Konajte podľa svojho postavenia, ja tiež budem konať, a čoskoro sa dozviete. (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 11:93; 39:39
- Ten, kto sa stavia proti Allahovi a Jeho poslovi, pre neho je pekelný oheň, v ktorom bude večne. (اللَّهَ وَرَسُولَهُ فَأَنَّ لَهُ نَارَ جَهَنَّمَ خَالِدًا فِيهَا) 9:63; 72:23
- Na ich srdcia sme dali závoje, aby mu nerozumeli, a do ich uší hluchotu. (عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا) 17:46; 18:57
- Do ktoréhokoľvek mesta sme poslali varovateľa, jeho bohatí obyvatelia povedali: My. (فِي قَرْيَةٍ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَا إِنَّا) 34:34; 43:23
- Povedali: Popros za nás svojho Pána, aby nám objasnil, aká je. (قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَ) 2:68; 2:70
- Oni povedia: Allah. Povedz: Chvála Allahovi! Ale väčšina z nich. (لَيَقُولُنَّ اللَّهُ قُلِ الْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا) 29:63; 31:25
- A odpoveď jeho ľudu bola len, že povedali: Vyžeňte ich! (وَمَا كَانَ جَوَابَ قَوْمِهِ إِلَّا أَن قَالُوا أَخْرِجُوهُم) 7:82; 27:56
- Pod ktorými tečú rieky, v nich budú večne; to je veľký úspech. (تَحْتَهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا ذَلِكَ الْفَوْزُ الْعَظِيمُ) 9:100; 64:9
- Tí sú na správnej ceste od svojho Pána, a tí sú úspešní. (أُولَئِكَ عَلَى هُدًى مِّن رَّبِّهِمْ وَأُولَئِكَ هُمُ الْمُفْلِحُونَ) 2:5; 31:5
- Toho, koho postihne ponižujúci trest a koho postihne večný trest. (مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ) 11:39; 39:40
- Choďte po zemi a pozrite, aký bol koniec tých, ktorí (pravdu) vyvracali. (فَسِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ الْمُكَذِّبِينَ) 3:137; 16:36
- Nikdy si to nebudú želať kvôli tomu, čo ich ruky poslali dopredu, a Allah pozná nespravodlivých. (يَتَمَنَّوْهُ أَبَدًا بِمَا قَدَّمَتْ أَيْدِيهِمْ وَاللَّهُ عَلِيمٌ بِالظَّالِمِينَ) 2:95; 62:7
- On najlepšie vie, kto zablúdil z Jeho cesty, a On najlepšie vie. (هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ) 53:30; 68:7
- Veru, Allah je môj Pán a váš Pán, preto Ho uctievajte; toto je priama cesta. (إِنَّ اللَّهَ رَبِّي وَرَبُّكُمْ فَاعْبُدُوهُ هَذَا صِرَاطٌ مُّسْتَقِيمٌ) 3:51; 19:36
- On je láskavý k ľuďom, ale väčšina z nich nie je vďačná. (لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ) 10:60; 27:73
- Nebesia a zem a to, čo je medzi nimi, sme stvorili iba v pravde a na určený čas. (السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ وَأَجَلٍ مُّسَمًّى) 30:8; 46:3
- Nechaj ich, nech sa ponárajú do planých rečí a hrajú sa, kým nestretnú svoj deň, ktorý im bol sľúbený. (فَذَرْهُمْ يَخُوضُوا وَيَلْعَبُوا حَتَّى يُلَاقُوا يَوْمَهُمُ الَّذِي يُوعَدُونَ) 43:83; 70:42
- Keď stretnú tých, čo uverili, hovoria: Uverili sme, a keď sú sami. (وَإِذَا لَقُوا الَّذِينَ آمَنُوا قَالُوا آمَنَّا وَإِذَا خَلَوْا) 2:14; 2:76
- Dodržiavajú Tóru a Evanjelium a to, čo im bolo zoslané od ich Pána. (أَقَامُوا التَّوْرَاةَ وَالْإِنجِيلَ وَمَا أُنزِلَ إِلَيْهِم مِّن رَّبِّهِمْ) 5:66; 5:68
- On vie, čo je pred nimi a čo za nimi, zatiaľ čo oni to nevedia obsiahnuť. (يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ) 2:255; 20:110
- On je ten, ktorý stvoril nebesia a zem v šiestich dňoch. (وَهُوَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ) 11:7; 57:4
- Veru, v tom je znamenie pre vás, ak ste veriaci. (إِنَّ فِي ذَلِكَ لَآيَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ) 2:248; 3:49
- Čo zabránilo ľuďom uveriť, keď k nim prišlo správne vedenie? (وَمَا مَنَعَ النَّاسَ أَن يُؤْمِنُوا إِذْ جَاءَهُمُ الْهُدَى) 17:94; 18:55
- Oni pridávali Allahovi spoločníkov, aby zvádzali z Jeho cesty. Povedz: Užívajte si! (وَجَعَلُوا لِلَّهِ أَندَادًا لِّيُضِلُّوا عَن سَبِيلِهِ قُلْ تَمَتَّعُوا) 14:30; 39:8
- A divili sa, že k nim prišiel varovateľ spomedzi nich, a neveriaci povedali: Toto. (وَعَجِبُوا أَن جَاءَهُم مُّنذِرٌ مِّنْهُمْ وَقَالَ الْكَافِرُونَ هَذَا) 38:4; 50:2
- Tvoj Pán najlepšie vie, kto zablúdil z Jeho cesty. (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ) 53:30; 68:7
- Podobný tomu, kto rozdáva svoj majetok na parádu ľuďom a neverí v Allaha. (كَالَّذِي يُنفِقُ مَالَهُ رِئَاءَ النَّاسِ وَلَا يُؤْمِنُ بِاللَّهِ) 2:264; 4:38
- Dávajte z toho, čo sme vám uštedrili, skôr než príde. (أَنفِقُوا مِمَّا رَزَقْنَاكُم مِّن قَبْلِ أَن يَأْتِيَ) 2:254; 63:10
- On vám podrobil to, čo je na nebesiach a na zemi. (سَخَّرَ لَكُم مَّا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 31:20; 45:13
- My sme naozaj v pochybnostiach o tom, k čomu nás vyzývate. (وَإِنَّنَا لَفِي شَكٍّ مِّمَّا تَدْعُونَا إِلَيْهِ مُرِيبٍ) 11:62; 14:9
- Tvoj Pán veru rozširuje obživu, komu chce, a odmeriava ju. Veru, On. (إِنَّ رَبَّكَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ وَيَقْدِرُ إِنَّهُ) 17:30; 34:36
- Pán nebies a zeme a toho, čo je medzi nimi, ak ste presvedčení. (رَبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا إِن كُنتُم مُّوقِنِينَ) 26:24; 44:7
- Uverili sme v Allaha a v to, čo bolo zoslané nám, a v to, čo bolo zoslané. (آمَنَّا بِاللَّهِ وَمَا أُنزِلَ إِلَيْنَا وَمَا أُنزِلَ إِلَى) 2:136; 3:199
- A tých, čo boli nespravodliví, zastihol hrozný zvuk a zostali ležať v svojich domoch na kolenách. (وَأَخَذَ الَّذِينَ ظَلَمُوا الصَّيْحَةُ فَأَصْبَحُوا فِي دِيَارِهِمْ جَاثِمِينَ) 11:67; 11:94
- Nie je pre vás hriech v tom, čo ony urobia o sebe. (فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِي أَنفُسِهِنَّ) 2:234; 2:240
- Tvoj Pán najlepšie vie, kto zablúdil z Jeho cesty, a On. (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ) 53:30; 68:7
- S duchom (zjavením) z Jeho rozkazu na toho, koho chce zo Svojich služobníkov. (بِالرُّوحِ مِنْ أَمْرِهِ عَلَى مَن يَشَاءُ مِنْ عِبَادِهِ) 16:2; 40:15
- A dali sme Ježišovi, synovi Márie, jasné znamenia a podporili sme ho Duchom svätým. (وَآتَيْنَا عِيسَى ابْنَ مَرْيَمَ الْبَيِّنَاتِ وَأَيَّدْنَاهُ بِرُوحِ الْقُدُسِ) 2:87; 2:253
- Aby v Deň zmŕtvychvstania rozsúdil medzi nimi to, v čom sa rozchádzali. (لَيَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ) 16:124; 22:69
- A prevrátili sme mesto hore nohami a dali sme na nich pršať kamene z páleného ílu. (جَعَلْنَا عَالِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَةً مِّن سِجِّيلٍ) 11:82; 15:74
- Je im jedno, či ich varuješ alebo nie, oni neveria. (سَوَاءٌ عَلَيْهِمْ أَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ) 2:6; 36:10
- Okrem ľudí, tak si želajte smrť, ak ste pravdiví. (مِّن دُونِ النَّاسِ فَتَمَنَّوُا الْمَوْتَ إِن كُنتُمْ صَادِقِينَ) 2:94; 62:6
- Allaha, nemáte iného boha okrem Neho. Či sa nebudete báť? (اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 23:23; 23:32
- Či ti ukážeme časť z toho, čím im hrozíme, alebo ťa k Sebe povoláme, k Nám sa vrátia. (وَإِمَّا نُرِيَنَّكَ بَعْضَ الَّذِي نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا) 10:46; 40:77
- Povedali: Či keď zomrieme a staneme sa prachom a kosťami, budeme vzkriesení? (قَالُوا أَإِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَامًا أَإِنَّا لَمَبْعُوثُونَ) 23:82; 56:47
- Dobro je v ruke Allaha; On ho dáva, komu chce. A Allah. (إِنَّ الْفَضْلَ بِيَدِ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ) 3:73; 57:29
- A budete vrátení k Tomu, ktorý pozná nepoznateľné i zjavné, a On vás bude informovať o tom, čo ste robili. (إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:105; 62:8
- Ó, vy, ktorí veríte! Pamätajte na Allahovu priazeň voči vám, keď. (يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا نِعْمَتَ اللَّهِ عَلَيْكُمْ إِذْ) 5:11; 33:9
- A pred tebou sme poslali iba mužov, ktorým sme dali zjavenie. (وَمَا أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِي إِلَيْهِم) 12:109; 16:43
- On mu odpustí hriechy a uvedie ho do rajských záhrad, pod ktorými tečú rieky. (يُكَفِّرْ عَنْهُ سَيِّئَاتِهِ وَيُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا) 64:9; 66:8
- Kto je chorý alebo na cestách, nech sa postí rovnaký počet iných dní. (مَّرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ) 2:184; 2:185
- Oni nasledujú iba dohady a iba sa domnievajú. (إِن يَتَّبِعُونَ إِلَّا الظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ) 6:116; 10:66
- Vzor výborný pre toho, kto dúfa v Allaha a v posledný deň. (أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الْآخِرَ) 33:21; 60:6
- A nestvorili sme nebesia a zem a to, čo je medzi nimi, okrem s pravdou. (وَمَا خَلَقْنَا السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ) 15:85; 46:3
- Vlož svoju ruku do svojho lona, vyjde biela, bez úhony. (يَدَكَ فِي جَيْبِكَ تَخْرُجْ بَيْضَاءَ مِنْ غَيْرِ سُوءٍ) 27:12; 28:32
- On vyvoláva Svojím milosrdenstvom, koho chce, a Allah je nesmierne štedrý. (يَخْتَصُّ بِرَحْمَتِهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 2:105; 3:74
- Či nevieš, že Allahovi patrí kráľovstvo nebies a zeme? (أَلَمْ تَعْلَمْ أَنَّ اللَّهَ لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ) 2:107; 5:40
- A čokoľvek dobrého pošlete pre seba dopredu, nájdete to u Allaha. (وَمَا تُقَدِّمُوا لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ اللَّهِ) 2:110; 73:20
- A nech vyjdeš odkiaľkoľvek, obráť svoju tvár smerom k Posvätnej mešite. (وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ) 2:149; 2:150
- Tí, čo boli pred vami, a nenájdeš zmenu v Allahovom zákone. (خَلَوْا مِن قَبْلُ وَلَن تَجِدَ لِسُنَّةِ اللَّهِ تَبْدِيلًا) 33:62; 48:23
- Ten, ktorému patrí všetko na nebesiach a na zemi. (الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 34:1; 42:53
- A žiadna žena neotehotnie a neporodí, iba s Jeho vedomím. (وَمَا تَحْمِلُ مِنْ أُنثَى وَلَا تَضَعُ إِلَّا بِعِلْمِهِ) 35:11; 41:47
- On podmanil noc, slnko a mesiac; všetko sa pohybuje do určenej lehoty. (اللَّيْلِ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ كُلٌّ يَجْرِي لِأَجَلٍ مُّسَمًّى) 35:13; 39:5
- Pod ktorými tečú rieky, v nich budú večne, a to je odmena. (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ جَزَاءُ) 5:85; 20:76
- Povedal: Nie, vaše duše vám navnukli niečo; trpezlivosť je krásna. (قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ) 12:18; 12:83
- To, čo je na nebesiach a na zemi, a že Allah. (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَأَنَّ اللَّهَ) 5:97; 22:64
- A ktorýkoľvek posol k nim prišiel, vysmievali sa mu. (وَمَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 15:11; 36:30
- Povedali: Ó, Mojžiš! Buď ty hodíš, alebo my hodíme? (قَالُوا يَامُوسَى إِمَّا أَن تُلْقِيَ وَإِمَّا أَن نَّكُونَ) 7:115; 20:65
- On vás usmrcuje; a niektorých z vás vracia do najbiednejšieho veku, aby. (يَتَوَفَّاكُمْ وَمِنكُم مَّن يُرَدُّ إِلَى أَرْذَلِ الْعُمُرِ لِكَيْ) 16:70; 22:5
- Pre nich sú u ich Pána rajské záhrady, pod ktorými tečú rieky, a budú v nich večne. (رَبِّهِمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:15; 3:136
- A na ich srdcia sme dali závoje, aby mu nerozumeli, a do ich uší hluchotu. (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ) 17:46; 18:57
- Sľub Allaha je pravdivý, ale väčšina z nich nevie. (إِنَّ وَعْدَ اللَّهِ حَقٌّ وَلَكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ) 10:55; 28:13
- To preto, že sa stávali proti Allahovi a Jeho poslovi; a kto sa stavia proti Allahovi. (ذَلِكَ بِأَنَّهُمْ شَاقُّوا اللَّهَ وَرَسُولَهُ وَمَن يُشَاقِقِ اللَّهَ) 8:13; 59:4
- A v deň, keď ich zavolá a povie: Kde sú tí, ktorých ste pokladali za mojich spoločníkov? (وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَائِيَ الَّذِينَ كُنتُمْ تَزْعُمُونَ) 28:62; 28:74
- Či nevideli, že Allah, ktorý stvoril nebesia a zem, je schopný stvoriť im podobných? (أَوَلَمْ يَرَوْا أَنَّ اللَّهَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ) 17:99; 46:33
- (On), ktorý vás stvoril z prachu, potom z kvapky semena, potom. (بِالَّذِي خَلَقَكَ مِن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ) 18:37; 40:67
- Povedali by: Náš Pane, prečo si nám neposlal posla, aby sme nasledovali Tvoje znamenia? (لَقَالُوا رَبَّنَا لَوْلَا أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ آيَاتِكَ) 20:134; 28:47
- Potom budú vrátení k svojmu Pánovi a On ich bude informovať o tom, čo robili. (ثُمَّ إِلَى رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُوا يَعْمَلُونَ) 6:108; 39:7
- Nemajú o tom žiadne vedomie; nasledujú iba dohady. (مَّا لَهُم بِذَلِكَ مِنْ عِلْمٍ إِنْ هُمْ إِلَّا) 43:20; 45:24
- Našli sme svojich otcov na tejto viere a my ideme v ich šľapajach. (إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِم) 43:22; 43:23
- Tí, ktorým bola daná Kniha, sa rozišli až potom, čo k nim prišlo vedenie. (الَّذِينَ أُوتُوا الْكِتَابَ إِلَّا مِن بَعْدِ مَا جَاءَهُمُ) 3:19; 98:4
- A keď Abrahám povedal: Môj Pane, učiň toto mesto bezpečným! (وَإِذْ قَالَ إِبْرَاهِيمُ رَبِّ اجْعَلْ هَذَا بَلَدًا آمِنًا) 2:126; 14:35
- On vám dal sluch, zrak a srdcia; a málo ste vďační. (وَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصَارَ وَالْأَفْئِدَةَ قَلِيلًا مَّا تَشْكُرُونَ) 32:9; 67:23
- Tí, ktorí sa hádajú o znameniach Allaha bez toho, aby k nim prišla moc. (الَّذِينَ يُجَادِلُونَ فِي آيَاتِ اللَّهِ بِغَيْرِ سُلْطَانٍ أَتَاهُمْ) 40:35; 40:56
- Nasledujte náboženstvo Abraháma, hanífa, a on nebol z modloslužobníkov. (فَاتَّبِعُوا مِلَّةَ إِبْرَاهِيمَ حَنِيفًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ) 3:95; 16:123
- A keď sme vás vyslobodili z rodu Faraónovho, ktorý vás podroboval najhoršiemu trápeniu. (وَإِذْ أَنجَيْنَاكُم مِّنْ آلِ فِرْعَوْنَ يَسُومُونَكُمْ سُوءَ الْعَذَابِ) 7:141; 14:6
- To je pravé náboženstvo, ale väčšina ľudí nevie. (ذَلِكَ الدِّينُ الْقَيِّمُ وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ) 12:40; 30:30
- Či si nevidel, že Allah vám podrobil to, čo je na. (أَلَمْ تَرَ أَنَّ اللَّهَ سَخَّرَ لَكُم مَّا فِي) 22:65; 31:20
- Neveriaci by povedali: Toto nie je nič iné ako zjavné čarodejníctvo. (لَقَالَ الَّذِينَ كَفَرُوا إِنْ هَذَا إِلَّا سِحْرٌ مُّبِينٌ) 6:7; 11:7
- A keď sú im prednášané Naše jasné znamenia, neveriaci hovoria. (وَإِذَا تُتْلَى عَلَيْهِمْ آيَاتُنَا بَيِّنَاتٍ قَالَ الَّذِينَ كَفَرُوا) 19:73; 46:7
- Záhrady Edenu, pod ktorými tečú rieky, a budú v nich večne. (جَنَّاتُ عَدْنٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 20:76; 98:8
- On tvorí, čo chce; a Allah nad všetkými vecami moc má. (مَا يَشَاءُ إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ) 24:45; 35:1
- Aby vám odpustil hriechy a odložil vás do určenej lehoty. (لِيَغْفِرَ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرَكُمْ إِلَى أَجَلٍ مُّسَمًّى) 14:10; 71:4
- Chcete nás odvrátiť od toho, čomu naši otcovia slúžili? (تُرِيدُونَ أَن تَصُدُّونَا عَمَّا كَانَ يَعْبُدُ آبَاؤُنَا) 14:10; 34:43
- A keď tvoj Pán povedal anjelom: Ja stvorím človeka z hliny. (وَإِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ إِنِّي خَالِقٌ بَشَرًا مِّن) 15:28; 38:71
- On je ten, ktorý posiela vetry ako zvestovateľov pred Svojím milosrdenstvom. (وَهُوَ الَّذِي يُرْسِلُ الرِّيَاحَ بُشْرًا بَيْنَ يَدَيْ رَحْمَتِهِ) 7:57; 25:48
- Povedz: Choďte po zemi a pozrite, aký bol koniec. (قُلْ سِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ) 27:69; 30:42
- V stvorení nebies a zeme a v striedaní noci a dňa (sú znamenia). (إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ) 2:164; 3:190
- Kto je ten, ktorý požičia Allahovi krásnu pôžičku, aby mu ju znásobil? (مَّن ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا فَيُضَاعِفَهُ) 2:245; 57:11
- Súď medzi nimi podľa toho, čo zoslal Allah, a nenasleduj ich žiadosti. (فَاحْكُم بَيْنَهُم بِمَا أَنزَلَ اللَّهُ وَلَا تَتَّبِعْ أَهْوَاءَهُمْ) 5:48; 5:49
- Či očakávajú niečo iné, než že k nim prídu anjeli, alebo príde tvoj Pán? (هَلْ يَنظُرُونَ إِلَّا أَن تَأْتِيَهُمُ الْمَلَائِكَةُ أَوْ يَأْتِيَ) 6:158; 16:33
- Veru, tí, ktorí si proti Allahovi vymýšľajú klamstvá, neuspejú. (إِنَّ الَّذِينَ يَفْتَرُونَ عَلَى اللَّهِ الْكَذِبَ لَا يُفْلِحُونَ) 10:69; 16:116
- Ako zvyk rodu Faraónovho a tých pred nimi – oni Naše znamenia za klamstvo vyhlasovali. (كَدَأْبِ آلِ فِرْعَوْنَ وَالَّذِينَ مِن قَبْلِهِمْ كَذَّبُوا بِآيَاتِنَا) 3:11; 8:54
- A zvestuje radostnú správu veriacim, ktorí konajú dobré skutky, že pre nich je odmena. (وَيُبَشِّرُ الْمُؤْمِنِينَ الَّذِينَ يَعْمَلُونَ الصَّالِحَاتِ أَنَّ لَهُمْ أَجْرًا) 17:9; 18:2
- Allah rozširuje obživu, komu chce zo Svojich služobníkov, a odmeriava ju. (اللَّهَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ مِنْ عِبَادِهِ وَيَقْدِرُ) 28:82; 29:62
- A budete vrátení k Tomu, ktorý pozná nepoznateľné i zjavné, a On vás bude informovať o tom, čo ste robili. (وَسَتُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ) 9:105; 62:8
- A pokrvní príbuzní sú si v Allahovej Knihe navzájom bližší. (وَأُولُو الْأَرْحَامِ بَعْضُهُمْ أَوْلَى بِبَعْضٍ فِي كِتَابِ اللَّهِ) 8:75; 33:6
